{"acl":["=X/postgres","postgres=X/postgres","anon=X/postgres","authenticated=X/postgres","service_role=X/postgres"],"name":"validate_event_capacity","owner":"postgres","result":"trigger","schema":"public","language":"plpgsql","settings":["search_path="""],"arguments":"","signature":"validate_event_capacity()","definition":"CREATE OR REPLACE FUNCTION public.validate_event_capacity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_registered bigint;
begin
  select count(*)
  into v_registered
  from public.registrations
  where event_id = new.id
    and status = 'registered';

  if new.capacity < v_registered then
    raise exception
      'Capacity cannot be less than existing registrations (%).',
      v_registered;
  end if;

  return new;
end;
$function$
","security_definer":false}

{"acl":["postgres=X/postgres","authenticated=X/postgres","service_role=X/postgres"],"name":"register_for_event","owner":"postgres","result":"registrations","schema":"public","language":"plpgsql","settings":["search_path="""],"arguments":"p_event_id uuid","signature":"register_for_event(uuid)","definition":"CREATE OR REPLACE FUNCTION public.register_for_event(p_event_id uuid)
 RETURNS registrations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_event public.events%rowtype;
  v_count integer;
  v_registration public.registrations%rowtype;
begin
  if v_user_id is null then
    raise exception 'You must be logged in.';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id = v_user_id
      and role = 'student'
  ) then
    raise exception 'Student access required.';
  end if;

  -- Lock event row to serialize registrations
  -- and prevent simultaneous overbooking.
  select *
  into v_event
  from public.events
  where id = p_event_id
  for update;

  if not found then
    raise exception 'Event not found.';
  end if;

  if v_event.status <> 'published'
     or v_event.ends_at <= now() then
    raise exception 'Registration is closed.';
  end if;

  if exists (
    select 1
    from public.registrations
    where event_id = p_event_id
      and student_id = v_user_id
  ) then
    raise exception 'You are already registered.';
  end if;

  select count(*)
  into v_count
  from public.registrations
  where event_id = p_event_id
    and status = 'registered';

  if v_count >= v_event.capacity then
    raise exception 'This event is full.';
  end if;

  insert into public.registrations (
    event_id,
    student_id,
    status
  )
  values (
    p_event_id,
    v_user_id,
    'registered'
  )
  returning * into v_registration;

  return v_registration;
end;
$function$
","security_definer":true}
